import {
  deployWithRollback,
  blueGreenStrategy,
  getDeploymentStatus,
  getDeploymentConfig,
} from "@/lib/deployment";

function isAuthenticated(request: Request): boolean {
  const authHeader = request.headers.get("Authorization");
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return false;
  }
  const token = authHeader.slice(7);
  return token === API_KEY;
}

async function GET(request: Request) {
  if (!isAuthenticated(request)) {
    return NextResponse.json(
      { error: "Unauthorized" },
      { status: 401 }
    );
  }

  try {
    const status = getDeploymentStatus();
    const config = getDeploymentConfig();

    return NextResponse.json({
      status,
      config,
      timestamp: new Date().toISOString(),
    });
  } catch (error) {
    return NextResponse.json(
      {
        error: "Failed to get deployment status",
        message: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 }
    );
  }
}

async function POST(request: Request) {
  if (!isAuthenticated(request)) {
    return NextResponse.json(
      { error: "Unauthorized" },
      { status: 401 }
    );
  }

  try {
    const body = await request.json();
    const { version, strategy = "simple" } = body;

    if (!version) {
      return NextResponse.json(
        { error: "Version is required" },
        { status: 400 }
      );
    }

    if (process.env.NODE_ENV === "development") {
        console.info(`[API] Deployment requested for version ${version} using ${strategy} strategy`);
    }

    let result;
    if (strategy === "blue-green") {
      result = await blueGreenStrategy.deploy(version);
    } else {
      result = await deployWithRollback(version);
    }

    const statusCode = result.success ? 200 : 500;

    return NextResponse.json(result, { status: statusCode });
  } catch (error) {
    console.error("[API] Deployment failed:", error);

    return NextResponse.json(
      {
        success: false,
        message: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 }
    );
  }
}

async function DELETE(request: Request) {
  if (!isAuthenticated(request)) {
    return NextResponse.json(
      { error: "Unauthorized" },
      { status: 401 }
    );
  }

  try {
    if (process.env.NODE_ENV === "development") {
        console.info("[API] Rollback requested");
    }

    const result = await blueGreenStrategy.rollback();

    const statusCode = result.success ? 200 : 500;

    return NextResponse.json(result, { status: statusCode });
  } catch (error) {
    console.error("[API] Rollback failed:", error);

    return NextResponse.json(
      {
        success: false,
        message: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 }
    );
  }
}

async function GET(request: Request) {
  try {
    const { searchParams } = new URL(request.url);
    const isQuick = searchParams.get("quick") === "true";
    const format = searchParams.get("format") || "json";

    // Quick check for load balancers
    if (isQuick) {
      const { healthy } = await quickHealthCheck();

      if (healthy) {
        return new NextResponse("OK", {
          status: 200,
          headers: { "Content-Type": "text/plain" },
        });
      } else {
        return new NextResponse("UNHEALTHY", {
          status: 503,
          headers: { "Content-Type": "text/plain" },
        });
      }
    }

    // Comprehensive health check
    const healthResult = await performHealthCheck();

    // Check if rollback is needed
    const rollbackDecision = shouldRollback(healthResult);

    // Determine HTTP status
    let statusCode = 200;
    if (healthResult.status === "unhealthy") {
      statusCode = 503;
    } else if (healthResult.status === "degraded") {
      statusCode = 200; // Still serving traffic, but with issues
    }

    // Add rollback info if applicable
    const response = {
      ...healthResult,
      rollback: rollbackDecision.rollback ? {
        needed: true,
        reason: rollbackDecision.reason,
      } : {
        needed: false,
      },
    };

    if (format === "text") {
      // Import format function dynamically to avoid server/client mismatch
      const { formatHealthCheck } = await import("@/lib/health-check");
      return new NextResponse(formatHealthCheck(healthResult), {
        status: statusCode,
        headers: { "Content-Type": "text/plain" },
      });
    }

    return NextResponse.json(response, { status: statusCode });
  } catch (error) {
    console.error("Health check failed:", error);

    return NextResponse.json(
      {
        status: "unhealthy",
        timestamp: new Date().toISOString(),
        error: error instanceof Error ? error.message : "Unknown error",
      },
