interface Props {
  children: ReactNode;
  fallback?: ReactNode;
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
  resetKeys?: Array<string | number>;
  className?: string;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  static getDerivedStateFromError(error: Error): State {
    // Update state so the next render will show the fallback UI
    return { hasError: true, error, errorInfo: null };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    // Log error details
    if (process.env.NODE_ENV === "development") {
      console.error("ErrorBoundary caught an error:", error, errorInfo);
    }

    this.setState({ error, errorInfo });

    // Track error in analytics
    trackError(error, errorInfo.componentStack || undefined);

    // Call optional error handler
    this.props.onError?.(error, errorInfo);

    // In production, you might want to send to an error tracking service
    if (process.env.NODE_ENV === "production") {
      // Example: Sentry.captureException(error, { extra: errorInfo });
      this.reportError(error, errorInfo);
    }
  }

  componentDidUpdate(prevProps: Props) {
    // Reset error state if resetKeys change
    if (this.state.hasError && this.props.resetKeys) {
      const hasResetKeyChanged = this.props.resetKeys.some(
        (key, index) => key !== prevProps.resetKeys?.[index]
      );

      if (hasResetKeyChanged) {
        this.reset();
      }
    }
  }

  reset = () => {
    this.setState({ hasError: false, error: null, errorInfo: null });
  };

  private reportError(error: Error, errorInfo: ErrorInfo) {
    // Placeholder for error reporting service
    // You can integrate Sentry, LogRocket, or other services here
    const errorReport = {
      error: error.toString(),
      stack: error.stack,
      componentStack: errorInfo.componentStack,
      url: typeof window !== "undefined" ? window.location.href : "",
      userAgent: typeof window !== "undefined" ? navigator.userAgent : "",
      timestamp: new Date().toISOString(),
    };

    // Send to your error tracking endpoint
    // fetch('/api/log-error', { method: 'POST', body: JSON.stringify(errorReport) });
    if (process.env.NODE_ENV === "development") {
      console.info("Error report prepared:", errorReport);
    }
  }

  render() {
    if (this.state.hasError) {
      // Custom fallback UI
      if (this.props.fallback) {
        return this.props.fallback;
      }

      // Default error fallback UI
      return (
        <div className={cn("min-h-[400px] flex items-center justify-center p-6", this.props.className)}>
          <ErrorFallback 
            error={this.state.error} 
            errorInfo={this.state.errorInfo}
            onReset={this.reset}
          />
        </div>
      );
    }

    return this.props.children;
  }
}

