type WebVitalThreshold = {
  name: WebVitalName;
  good: number;
  poor: number;
  unit: string;
};

WEB_VITALS_THRESHOLDS: Record<WebVitalName, WebVitalThreshold> = {
  CLS: {
    name: "CLS",
    good: 0.1,
    poor: 0.25,
    unit: "",
  },
  FCP: {
    name: "FCP",
    good: 1800, // 1.8s
    poor: 3000, // 3s
    unit: "ms",
  },
  FID: {
    name: "FID",
    good: 100, // 100ms
    poor: 300, // 300ms
    unit: "ms",
  },
  INP: {
    name: "INP",
    good: 200, // 200ms
    poor: 500, // 500ms
    unit: "ms",
  },
  LCP: {
    name: "LCP",
    good: 2500, // 2.5s
    poor: 4000, // 4s
    unit: "ms",
  },
  TTFB: {
    name: "TTFB",
    good: 800, // 800ms
    poor: 1800, // 1.8s
    unit: "ms",
  },
}

type AlertConfig = {
  enabled: boolean;
  threshold: WebVitalRating;
  cooldownMs: number;
  webhookUrl?: string;
};

DEFAULT_ALERT_CONFIG: AlertConfig = {
  enabled: true,
  threshold: "poor",
  cooldownMs: 300000, // 5 minutes
}

// ============================================================================
// Web Vitals Monitoring State
// ============================================================================
type WebVitalsState = {
  metrics: Record<WebVitalName, number | null>;
  ratings: Record<WebVitalName, WebVitalRating>;
  alerts: Array<{
    name: WebVitalName;
    value: number;
    rating: WebVitalRating;
    timestamp: string;
  }>;
};

function getWebVitalRating(name: WebVitalName, value: number): WebVitalRating {
  const threshold = WEB_VITALS_THRESHOLDS[name];

  if (value <= threshold.good) {
    return "good";
  } else if (value <= threshold.poor) {
    return "needs-improvement";
  } else {
    return "poor";
  }
}

function formatWebVitalValue(name: WebVitalName, value: number): string {
  const threshold = WEB_VITALS_THRESHOLDS[name];

  if (threshold.unit === "ms") {
    return `${Math.round(value)}ms`;
  }

  return value.toFixed(3);
}

/**
 * Send alert for poor web vital
 */
async function sendWebVitalAlert(
  name: WebVitalName,
  value: number,
  rating: WebVitalRating,
  config: AlertConfig
): Promise<void> {
  const now = Date.now();

  // Check cooldown
  if (now - lastAlertTime[name] < config.cooldownMs) {
    return;
  }

  lastAlertTime[name] = now;

  const alertData = {
    type: "web-vital-alert",
    name,
    value,
    rating,
    threshold: WEB_VITALS_THRESHOLDS[name],
    timestamp: new Date().toISOString(),
    page: typeof window !== "undefined" ? window.location.pathname : "unknown",
  };

  // Log alert
  if (process.env.NODE_ENV === "development") {
    console.warn(`[Web Vitals Alert] ${name} is ${rating}: ${formatWebVitalValue(name, value)}`);
  }

  // Send to analytics
  trackEvent("web_vital_alert", {
    metric_name: name,
    metric_value: value,
    metric_rating: rating,
    page_path: alertData.page,
  });

  // Send to webhook if configured
  if (config.webhookUrl) {
    try {
      await fetch(config.webhookUrl, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(alertData),
      });
    } catch (error) {
      if (process.env.NODE_ENV === "development") {
        console.error("Failed to send web vital alert:", error);
      }
    }
  }

  // Send to internal endpoint
  if (typeof window !== "undefined") {
    const body = JSON.stringify(alertData);

    if (navigator.sendBeacon) {
      navigator.sendBeacon("/api/vitals/alert", body);
    } else {
      fetch("/api/vitals/alert", {
        method: "POST",
        body,
        keepalive: true,
      }).catch(() => undefined);
    }
  }
}

type RUMSession = {
  sessionId: string;
  startTime: number;
  pageViews: number;
  metrics: WebVitalsState;
};

/**
 * Generate unique session ID
 */
function generateSessionId(): string {
  return `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
}

/**
 * Initialize RUM session
 */
function initRUMSession(): RUMSession {
  return {
    sessionId: generateSessionId(),
    startTime: Date.now(),
    pageViews: 1,
    metrics: {
      metrics: {
        CLS: null,
        FCP: null,
        FID: null,
        INP: null,
        LCP: null,
        TTFB: null,
      },
      ratings: {
        CLS: "good",
        FCP: "good",
        FID: "good",
        INP: "good",
        LCP: "good",
        TTFB: "good",
      },
      alerts: [],
    },
  };
}

function reportWebVitals(
  metric: NextWebVitalsMetric,
  alertConfig: AlertConfig = DEFAULT_ALERT_CONFIG
) {
  const name = metric.name as WebVitalName;
  const value = metric.value;
  const rating = getWebVitalRating(name, value);

  // Log to console in development
  if (process.env.NODE_ENV === "development") {
    const color = rating === "good" ? "🟢" : rating === "needs-improvement" ? "🟡" : "🔴";
    console.info(`[Web Vitals] ${color} ${name}: ${formatWebVitalValue(name, value)} (${rating})`);
  }

  // Send to analytics
  trackEvent("web_vital", {
    metric_name: name,
    metric_value: value,
    metric_rating: rating,
    metric_id: metric.id,
    page_path: typeof window !== "undefined" ? window.location.pathname : "unknown",
  });

  // Check if alert needed
  if (alertConfig.enabled) {
    const shouldAlert =
      alertConfig.threshold === "poor"
        ? rating === "poor"
        : alertConfig.threshold === "needs-improvement"
        ? rating === "poor" || rating === "needs-improvement"
        : true;

    if (shouldAlert && rating !== "good") {
      sendWebVitalAlert(name, value, rating, alertConfig);
    }
  }

  // Send to custom endpoint
  if (process.env.NODE_ENV === "production" && typeof window !== "undefined") {
    const body = JSON.stringify({
      ...metric,
      rating,
      page: window.location.pathname,
      timestamp: Date.now(),
    });

    if (navigator.sendBeacon) {
      navigator.sendBeacon("/api/vitals", body);
      } else {
        fetch("/api/vitals", {
          body,
          method: "POST",
          keepalive: true,
        }).catch(() => undefined);
      }
  }
}

