function getAssetKind(name: string): AssetKind {
  const lower = name.toLowerCase();
  if (lower.endsWith(".dmg")) return "dmg";
  if (lower.endsWith(".msi")) return "msi";
  if (lower.endsWith(".exe")) return "exe";
  if (lower.endsWith(".appimage")) return "appimage";
  if (lower.endsWith(".deb")) return "deb";
  if (lower.endsWith(".rpm")) return "rpm";
  if (lower.endsWith(".tar.gz")) return "tar";
  if (lower.endsWith(".zip")) return "zip";
  return "other";
}

function formatBytes(value: number): string {
  if (!Number.isFinite(value) || value <= 0) return "—";
  const units = ["B", "KB", "MB", "GB"] as const;
  let current = value;
  let unitIndex = 0;
  while (current >= 1024 && unitIndex < units.length - 1) {
    current /= 1024;
    unitIndex += 1;
  }
  return `${current.toFixed(current >= 10 || unitIndex === 0 ? 0 : 1)} ${units[unitIndex]}`;
}

function pickInstallers(assets: GithubAsset[]): GithubAsset[] {
  return assets.filter((asset) => {
    const lower = asset.name.toLowerCase();
    if (lower.endsWith(".sig") || lower.endsWith("latest.json") || lower.endsWith(".json")) {
      return false;
    }
    if (lower.endsWith(".app.tar.gz")) {
      return false;
    }
    return INSTALLER_EXTENSIONS.some((ext) => lower.endsWith(ext));
  });
}

