      const payload = (await response.json()) as LatestReleaseClientPayload;
      if (!payload?.tag || !Array.isArray(payload.assets)) {
        return null;
      }
      cacheValue = payload;
      cacheAt = Date.now();
      return payload;
    })
    .catch(() => null)
    .finally(() => {
      inFlight = null;
    });

  return inFlight;
}

