type DocMeta = {
  slug: string;
  title: string;
  summary: string;
  section: string;
  order: number;
};

type DocHeading = {
  id: string;
  text: string;
  level: 2 | 3;
};

type DocEntry = {
  meta: DocMeta;
  content: string;
  headings: DocHeading[];
};

function slugify(value: string): string {
  const lowered = value.toLowerCase().trim();
  const ascii = lowered
    // Minimal TR transliteration for stable anchor ids.
    .replace(/ğ/g, "g")
    .replace(/ü/g, "u")
    .replace(/ş/g, "s")
    .replace(/ı/g, "i")
    .replace(/ö/g, "o")
    .replace(/ç/g, "c")
    // Strip common diacritics.
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "");

  return ascii
    .replace(/[^a-z0-9\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function parseHeadings(markdown: string): DocHeading[] {
  const headings: DocHeading[] = [];
  const lines = markdown.split("\n");
  for (const line of lines) {
    const match = line.match(/^(##|###)\s+(.+)$/);
    if (!match) continue;
    const level = match[1] === "##" ? 2 : 3;
    const text = match[2].replace(/`/g, "").trim();
    headings.push({
      id: slugify(text),
      text,
      level
    });
  }
  return headings;
}

async function readDocFileForLocale(locale: Locale, fileName: string): Promise<DocEntry> {
  const filePath = path.join(DOCS_ROOT, locale, fileName);
  const fallbackPath = path.join(DOCS_ROOT, "en", fileName);
  const resolvedPath = await fs
    .access(filePath)
    .then(() => filePath)
    .catch(() => fallbackPath);
  const raw = await fs.readFile(resolvedPath, "utf8");
  const parsed = matter(raw);
  const slug = fileName.replace(/\.mdx?$/i, "");

  const meta: DocMeta = {
    slug,
    title: String(parsed.data.title ?? slug),
    summary: String(parsed.data.summary ?? ""),
    section: String(parsed.data.section ?? "General"),
    order: Number(parsed.data.order ?? 999),
  };

  return {
    meta,
    content: parsed.content.trim(),
    headings: parseHeadings(parsed.content)
  };
}

async function readDocs(locale: Locale): Promise<DocEntry[]> {
  const localeDir = path.join(DOCS_ROOT, locale);
  const fallbackDir = path.join(DOCS_ROOT, "en");
  const files = await fs
    .readdir(localeDir)
    .catch(() => fs.readdir(fallbackDir));
  const docs = await Promise.all(
    files
      .filter((file) => file.endsWith(".mdx") || file.endsWith(".md"))
      .map((file) => readDocFileForLocale(locale, file))
  );

  return docs.sort((a, b) => {
    if (a.meta.section !== b.meta.section) {
      return a.meta.section.localeCompare(b.meta.section);
    }
    if (a.meta.order !== b.meta.order) {
      return a.meta.order - b.meta.order;
    }
    return a.meta.title.localeCompare(b.meta.title);
  });
}

