type HealthCheckResult = {
  status: HealthStatus;
  timestamp: string;
  version: string;
  uptime: number;
  checks: Record<string, ComponentHealth>;
  overall: {
    healthy: number;
    degraded: number;
    unhealthy: number;
    total: number;
  };
};

type ComponentHealth = {
  status: HealthStatus;
  responseTime: number;
  message?: string;
  lastChecked: string;
};

type PerformanceMemory = {
  usedJSHeapSize: number;
  totalJSHeapSize: number;
  jsHeapSizeLimit?: number;
};

// 3 seconds response time
/**
 * Check GitHub API connectivity
 */
async function checkGitHubAPI(): Promise<ComponentHealth> {
  const startTime = Date.now();

  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), HEALTH_CHECK_TIMEOUT);

    const response = await fetch("https://api.github.com/status", {
      signal: controller.signal,
    });

    clearTimeout(timeoutId);
    const responseTime = Date.now() - startTime;

    if (!response.ok) {
      return {
        status: "degraded",
        responseTime,
        message: `GitHub API returned ${response.status}`,
        lastChecked: new Date().toISOString(),
      };
    }

    return {
      status: responseTime > DEGRADED_THRESHOLD ? "degraded" : "healthy",
      responseTime,
      lastChecked: new Date().toISOString(),
    };
  } catch (error) {
    return {
      status: "unhealthy",
      responseTime: Date.now() - startTime,
      message: error instanceof Error ? error.message : "Unknown error",
      lastChecked: new Date().toISOString(),
    };
  }
}

/**
 * Check application memory usage
 */
function checkMemory(): ComponentHealth {
  const startTime = Date.now();

  try {
    // For Node.js environment
    if (typeof process !== "undefined" && process.memoryUsage) {
      const usage = process.memoryUsage();
      const heapUsedMB = Math.round(usage.heapUsed / 1024 / 1024);
      const heapTotalMB = Math.round(usage.heapTotal / 1024 / 1024);
      const usagePercent = (heapUsedMB / heapTotalMB) * 100;

      let status: HealthStatus = "healthy";
      let message: string | undefined;

      if (usagePercent > 90) {
        status = "unhealthy";
        message = `Memory usage critical: ${usagePercent.toFixed(1)}%`;
      } else if (usagePercent > 70) {
        status = "degraded";
        message = `Memory usage high: ${usagePercent.toFixed(1)}%`;
      }

      return {
        status,
        responseTime: Date.now() - startTime,
        message,
        lastChecked: new Date().toISOString(),
      };
    }

    // For browser environment
    if (typeof performance !== "undefined" && "memory" in performance) {
      const memory = (performance as Performance & { memory?: PerformanceMemory }).memory;
      if (!memory) {
        return {
          status: "healthy",
          responseTime: Date.now() - startTime,
          message: "Memory check not available in this environment",
          lastChecked: new Date().toISOString(),
        };
      }
      const usedMB = Math.round(memory.usedJSHeapSize / 1024 / 1024);
      const totalMB = Math.round(memory.totalJSHeapSize / 1024 / 1024);

      return {
        status: "healthy",
        responseTime: Date.now() - startTime,
        message: `Browser memory: ${usedMB}MB / ${totalMB}MB`,
        lastChecked: new Date().toISOString(),
      };
    }

    return {
      status: "healthy",
      responseTime: Date.now() - startTime,
      message: "Memory check not available in this environment",
      lastChecked: new Date().toISOString(),
    };
  } catch {
    return {
      status: "degraded",
      responseTime: Date.now() - startTime,
      message: "Could not check memory",
      lastChecked: new Date().toISOString(),
    };
  }
}

/**
 * Check disk space (Node.js only)
 */
async function checkDiskSpace(): Promise<ComponentHealth> {
  const startTime = Date.now();

  try {
