/**
 * Check Tauri runtime (if applicable)
 */
function checkTauriRuntime(): ComponentHealth {
  const startTime = Date.now();

  try {
    // Check if running in Tauri
    const isTauri =
      typeof window !== "undefined" &&
      !!(window as Window & { __TAURI__?: unknown }).__TAURI__;

    if (isTauri) {
      return {
        status: "healthy",
        responseTime: Date.now() - startTime,
        message: "Tauri runtime detected",
        lastChecked: new Date().toISOString(),
      };
    }

    return {
      status: "healthy",
      responseTime: Date.now() - startTime,
      message: "Running in browser mode (not Tauri)",
      lastChecked: new Date().toISOString(),
    };
  } catch {
    return {
      status: "degraded",
      responseTime: Date.now() - startTime,
      message: "Could not determine runtime",
      lastChecked: new Date().toISOString(),
    };
  }
}

/**
 * Get application uptime in seconds
 */
function getUptime(): number {
  return Math.floor((Date.now() - startTime) / 1000);
}

async function performHealthCheck(): Promise<HealthCheckResult> {
  const [githubHealth, memoryHealth, diskHealth, runtimeHealth] = await Promise.all([
    checkGitHubAPI(),
    checkMemory(),
    checkDiskSpace(),
    Promise.resolve(checkTauriRuntime()),
  ]);

  const checks = {
    github_api: githubHealth,
    memory: memoryHealth,
    disk: diskHealth,
    runtime: runtimeHealth,
  };

  // Calculate overall health
  const values = Object.values(checks);
  const healthy = values.filter((v) => v.status === "healthy").length;
  const degraded = values.filter((v) => v.status === "degraded").length;
  const unhealthy = values.filter((v) => v.status === "unhealthy").length;

  // Determine overall status
  let status: HealthStatus = "healthy";
  if (unhealthy > 0) {
    status = "unhealthy";
  } else if (degraded > 0) {
    status = "degraded";
  }

  return {
    status,
    timestamp: new Date().toISOString(),
    version: "1.0.0",
    uptime: getUptime(),
    checks,
    overall: {
      healthy,
      degraded,
      unhealthy,
      total: values.length,
    },
  };
}

checks = {
    github_api: githubHealth,
    memory: memoryHealth,
    disk: diskHealth,
    runtime: runtimeHealth,
  }

async function quickHealthCheck(): Promise<{ healthy: boolean }> {
  const result = await performHealthCheck();
  return { healthy: result.status === "healthy" };
}

function shouldRollback(healthResult: HealthCheckResult): {
  rollback: boolean;
  reason?: string;
} {
  // Rollback if any critical component is unhealthy
  if (healthResult.checks.github_api?.status === "unhealthy") {
    return {
      rollback: true,
      reason: "GitHub API connectivity lost",
    };
  }

  if (healthResult.checks.memory?.status === "unhealthy") {
    return {
      rollback: true,
      reason: "Critical memory usage",
    };
  }

  // Rollback if more than 50% of checks are unhealthy
  const unhealthyPercent = (healthResult.overall.unhealthy / healthResult.overall.total) * 100;
  if (unhealthyPercent > 50) {
    return {
      rollback: true,
      reason: `More than 50% of health checks failing (${unhealthyPercent.toFixed(0)}%)`,
    };
  }

  return { rollback: false };
}

function formatHealthCheck(result: HealthCheckResult): string {
  const lines = [
    `Health Status: ${result.status.toUpperCase()}`,
    `Timestamp: ${result.timestamp}`,
    `Version: ${result.version}`,
    `Uptime: ${Math.floor(result.uptime / 60)}m ${result.uptime % 60}s`,
    "",
    "Component Checks:",
  ];

  for (const [name, check] of Object.entries(result.checks)) {
    const icon = check.status === "healthy" ? "✓" : check.status === "degraded" ? "⚠" : "✗";
    lines.push(`  ${icon} ${name}: ${check.status} (${check.responseTime}ms)`);
    if (check.message) {
      lines.push(`    ${check.message}`);
    }
  }

  lines.push("");
  lines.push(`Overall: ${result.overall.healthy} healthy, ${result.overall.degraded} degraded, ${result.overall.unhealthy} unhealthy`);

  return lines.join("\n");
}

interface CookieConsentContextType {
    preferences: CookiePreferences;
    showBanner: boolean;
    hasConsented: boolean;
    acceptAll: () => void;
    rejectAll: () => void;
    savePreferences: (prefs: CookiePreferences) => void;
    resetConsent: () => void;
    openSettings: () => void;
    closeSettings: () => void;
    isSettingsOpen: boolean;
}

function CookieConsentProvider({ children }: { children: React.ReactNode }) {
    const [preferences, setPreferences] = useState<CookiePreferences>(DEFAULT_PREFERENCES);
    const [showBanner, setShowBanner] = useState(false);
    const [isSettingsOpen, setIsSettingsOpen] = useState(false);
    const [hasConsented, setHasConsented] = useState(false);

    useEffect(() => {
        // Check for existing consent
        const stored = localStorage.getItem(COOKIE_KEY);
        if (stored) {
            try {
                const parsed = JSON.parse(stored);
                setPreferences({ ...DEFAULT_PREFERENCES, ...parsed, necessary: true });
                setShowBanner(false);
                setHasConsented(true);
            } catch {
                // Invalid JSON, treat as no consent
                setShowBanner(true);
                setHasConsented(false);
            }
        } else {
            // No consent found, show banner
            setShowBanner(true);
            setHasConsented(false);
        }
    }, []);

    const saveToStorage = (prefs: CookiePreferences) => {
        localStorage.setItem(COOKIE_KEY, JSON.stringify(prefs));
        setPreferences(prefs);
        setShowBanner(false);
        setIsSettingsOpen(false);
        setHasConsented(true);

        // Trigger GTM/Analytics update here if needed (e.g. window.gtag('consent', ...))
    };

    const acceptAll = () => {
        saveToStorage({ necessary: true });
    };

    const rejectAll = () => {
        saveToStorage({ necessary: true });
    };

    const savePreferences = (prefs: CookiePreferences) => {
        // Today we only support "necessary" cookies; keep the shape for future expansion.
        saveToStorage({ ...prefs, necessary: true });
    };

    const resetConsent = () => {
        localStorage.removeItem(COOKIE_KEY);
        setPreferences(DEFAULT_PREFERENCES);
        setShowBanner(true);
        setHasConsented(false);
    };

    const openSettings = () => setIsSettingsOpen(true);
    const closeSettings = () => setIsSettingsOpen(false);

    // if (!isInitialized) return null; // Removed to prevent blocking app render

    return (
        <CookieConsentContext.Provider
            value={{
                preferences,
                showBanner,
                hasConsented,
                acceptAll,
                rejectAll,
                savePreferences,
                resetConsent,
                openSettings,
                closeSettings,
                isSettingsOpen,
            }}
        >
            {children}
        </CookieConsentContext.Provider>
    );
}

