pub fn load_baseline(path: &Path) -> Result<Baseline> {
    let raw = fs::read_to_string(path)
        .with_context(|| format!("Failed to read baseline file: {}", path.display()))?;
    let baseline = serde_json::from_str::<Baseline>(&raw)
        .with_context(|| format!("Failed to parse baseline JSON: {}", path.display()))?;
    Ok(baseline)
}

pub fn resolve_baseline_path(root: &Path, candidate: Option<PathBuf>) -> Option<PathBuf> {
    if let Some(path) = candidate {
        return Some(path);
    }
    let default = root.join(".guardian").join("baseline.json");
    if default.exists() {
        return Some(default);
    }
    None
}

pub fn is_sensitive_file(path: &Path) -> bool {
    const SENSITIVE_NAMES: &[&str] = &[
        ".env",
        ".env.local",
        ".env.production",
        ".npmrc",
        ".pypirc",
        "id_rsa",
        "id_ed25519",
        "credentials",
        "secrets",
        "config.json",
        "secrets.yml",
        "secrets.yaml",
    ];
    const SENSITIVE_EXTS: &[&str] = &["key", "pem", "p12", "pfx", "cer", "crt", "der"];

    let name = path
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or_default()
        .to_lowercase();
    let ext = path
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or_default()
        .to_lowercase();

    if SENSITIVE_EXTS.iter().any(|e| ext == *e) {
        return true;
    }
    if SENSITIVE_NAMES.iter().any(|s| name.contains(s)) {
        return true;
    }

    false
}

pub fn mask_inline_secrets(content: &str) -> String {
    let mut out = content.to_string();

    if out.contains("-----BEGIN") && out.contains("PRIVATE KEY-----") {
        out = redact_private_key_blocks(&out);
    }

    out = OPENAI_KEY.replace_all(&out, "[REDACTED_OPENAI_KEY]").to_string();
    out = ANTHROPIC_KEY
        .replace_all(&out, "[REDACTED_ANTHROPIC_KEY]")
        .to_string();
    out = GITHUB_TOKEN
        .replace_all(&out, "[REDACTED_GITHUB_TOKEN]")
        .to_string();
    out = AWS_ACCESS_KEY
        .replace_all(&out, "[REDACTED_AWS_ACCESS_KEY]")
        .to_string();
    out = EMAIL.replace_all(&out, "[REDACTED_EMAIL]").to_string();

    out
}

fn redact_private_key_blocks(content: &str) -> String {
    let mut out = String::with_capacity(content.len());
    let mut in_block = false;
    for line in content.lines() {
        if line.contains("-----BEGIN") && line.contains("PRIVATE KEY-----") {
            in_block = true;
            out.push_str("[REDACTED_PRIVATE_KEY_BLOCK]\n");
            continue;
        }
        if in_block {
            if line.contains("-----END") && line.contains("PRIVATE KEY-----") {
                in_block = false;
            }
            continue;
        }
        out.push_str(line);
        out.push('\n');
    }
    out
}

mod tests {
    use super::*;

    #[test]
    fn masks_email_addresses() {
        let input = "Contact: test@example.com";
        let out = mask_inline_secrets(input);
        assert!(out.contains("[REDACTED_EMAIL]"));
        assert!(!out.contains("test@example.com"));
    }
}

fn masks_email_addresses() {
        let input = "Contact: test@example.com";
        let out = mask_inline_secrets(input);
        assert!(out.contains("[REDACTED_EMAIL]"));
        assert!(!out.contains("test@example.com"));
    }

pub struct ManifestLimits {
    pub max_files: usize,
    pub max_file_bytes: u64,
    pub max_batch_size: usize,
}

impl RunManifest {
    pub fn new(
        root: String,
        workspace_id: String,
        rules_hash: String,
        scan_profile: String,
        limits: ManifestLimits,
        mut file_inventory: Vec<FileInventoryEntry>,
    ) -> Self {
        // Stable ordering for deterministic hashing.
        file_inventory.sort_by(|a, b| a.path_rel.cmp(&b.path_rel).then_with(|| a.reason.cmp(&b.reason)));

        Self {
            schema_version: 1,
            generated_at: Utc::now().to_rfc3339(),
            guardian_version: env!("CARGO_PKG_VERSION").to_string(),
            root,
            workspace_id,
            rules_hash,
            scan_profile,
            limits,
            file_inventory,
        }
    }

    /// Deterministic hash that excludes generated_at.
    pub fn stable_hash_hex(&self) -> String {
        let hashable = HashableManifest {
            schema_version: self.schema_version,
            guardian_version: &self.guardian_version,
            root: &self.root,
            workspace_id: &self.workspace_id,
            rules_hash: &self.rules_hash,
            scan_profile: &self.scan_profile,
            limits: &self.limits,
            file_inventory: &self.file_inventory,
        };
        let payload = serde_json::to_vec(&hashable).unwrap_or_default();
        let mut hasher = Sha256::new();
        hasher.update(&payload);
        hex::encode(hasher.finalize())
    }
}

pub fn new(
        root: String,
        workspace_id: String,
        rules_hash: String,
        scan_profile: String,
        limits: ManifestLimits,
        mut file_inventory: Vec<FileInventoryEntry>,
    ) -> Self {
        // Stable ordering for deterministic hashing.
        file_inventory.sort_by(|a, b| a.path_rel.cmp(&b.path_rel).then_with(|| a.reason.cmp(&b.reason)));

        Self {
            schema_version: 1,
            generated_at: Utc::now().to_rfc3339(),
            guardian_version: env!("CARGO_PKG_VERSION").to_string(),
            root,
            workspace_id,
            rules_hash,
            scan_profile,
            limits,
            file_inventory,
        }
    }

/// Deterministic hash that excludes generated_at.

pub fn stable_hash_hex(&self) -> String {
        let hashable = HashableManifest {
            schema_version: self.schema_version,
            guardian_version: &self.guardian_version,
            root: &self.root,
            workspace_id: &self.workspace_id,
            rules_hash: &self.rules_hash,
            scan_profile: &self.scan_profile,
            limits: &self.limits,
            file_inventory: &self.file_inventory,
        };
        let payload = serde_json::to_vec(&hashable).unwrap_or_default();
        let mut hasher = Sha256::new();
        hasher.update(&payload);
        hex::encode(hasher.finalize())
    }

let hashable = HashableManifest {
            schema_version: self.schema_version,
            guardian_version: &self.guardian_version,
            root: &self.root,
            workspace_id: &self.workspace_id,
            rules_hash: &self.rules_hash,
            scan_profile: &self.scan_profile,
            limits: &self.limits,
            file_inventory: &self.file_inventory,
        };

