const newFindings = findings.filter((f) => f?.is_new);

const short = (value, n = 12) => {
  if (!value || typeof value !== "string") return "n/a";
  return value.length > n ? value.slice(0, n) : value;
};

let md = "";
md += "## Guardian Scan\n\n";
