    };

fn normalize_rel_file_path(workspace_root: &Path, file_path: &str) -> String {
    let input = Path::new(file_path);

    if !input.is_absolute() {
        let rel = file_path.trim().trim_start_matches("./").to_string();
        return rel.replace('\\', "/");
    }

    if let Ok(rel) = input.strip_prefix(workspace_root) {
        return rel
            .to_string_lossy()
            .replace('\\', "/")
            .trim_start_matches("./")
            .to_string();
    }

    let canonical_root =
        dunce::canonicalize(workspace_root).unwrap_or_else(|_| workspace_root.to_path_buf());
    let canonical_input = dunce::canonicalize(input).unwrap_or_else(|_| input.to_path_buf());
    if let Ok(rel) = canonical_input.strip_prefix(&canonical_root) {
        return rel
            .to_string_lossy()
            .replace('\\', "/")
            .trim_start_matches("./")
            .to_string();
    }

    file_path.trim().replace('\\', "/")
}

fn is_file_token(token: &str) -> bool {
    let lower = token.to_lowercase();
    if lower.contains('/') || lower.contains('\\') {
        return true;
    }
    if FILE_TOKEN_EXTENSIONS.iter().any(|ext| lower.ends_with(ext)) {
        return true;
    }
    if let Some(idx) = lower.rfind('.') {
        let suffix = &lower[idx + 1..];
        return !suffix.is_empty()
            && suffix.len() <= 6
            && suffix.chars().all(|c| c.is_ascii_alphanumeric());
    }
    false
}

fn clean_token(token: &str) -> String {
    token
        .trim_matches(|c: char| {
            !(c.is_alphanumeric() || c == '.' || c == '_' || c == '-' || c == '/' || c == '\\')
        })
        .to_string()
}

fn extract_file_tokens(query: &str) -> Vec<String> {
    let mut tokens = Vec::new();
    let normalized = query.replace("\\", "/");
    for raw in normalized.split_whitespace() {
        let token = clean_token(raw);
        let token = token
            .trim_end_matches(|c: char| c == '.' || c == ',' || c == ':' || c == ';')
            .to_string();
        if token.is_empty() {
            continue;
        }
        if is_file_token(&token) {
            tokens.push(token);
        }
    }
    tokens
}

let token = token
            .trim_end_matches(|c: char| c == '.' || c == ',' || c == ':' || c == ';')
            .to_string();

fn resolve_explicit_files(root: &str, tokens: &[String]) -> Vec<PathBuf> {
    let mut results = Vec::new();
    let mut seen: HashSet<String> = HashSet::new();
    let root_path = Path::new(root);

    let root_canon = root_path.canonicalize();

    for token in tokens {
        if results.len() >= 3 {
            break;
        }

        let candidate = Path::new(token);
        let candidate_path = if candidate.is_absolute() {
            candidate.to_path_buf()
        } else {
            Path::new(root).join(candidate)
        };

        if candidate_path.exists() && candidate_path.is_file() {
            if !is_within_root_cached(&root_canon, &candidate_path) {
                continue;
            }
            let key = candidate_path.to_string_lossy().to_string();
            if seen.insert(key) {
                results.push(candidate_path);
            }
            continue;
        }

        let file_name = candidate.file_name().and_then(|s| s.to_str());
        if let Some(file_name) = file_name {
            let walker = WalkBuilder::new(root)
                .hidden(false)
                .git_ignore(true)
                .build();

            for result in walker {
                if results.len() >= 3 {
                    break;
                }
                if let Ok(entry) = result {
                    if entry.file_type().map(|f| f.is_file()).unwrap_or(false)
                        && entry.file_name().to_string_lossy() == file_name
                    {
                        let path = entry.path().to_path_buf();
                        if !is_within_root_cached(&root_canon, &path) {
                            continue;
                        }
                        let key = path.to_string_lossy().to_string();
                        if seen.insert(key) {
                            results.push(path);
                        }
                        break;
                    }
                }
            }
        }
    }

    results
}

let candidate_path = if candidate.is_absolute() {
            candidate.to_path_buf()
        } else {
            Path::new(root).join(candidate)
        };

fn is_within_root_cached(root_canon: &std::io::Result<PathBuf>, candidate: &Path) -> bool {
    let Ok(root_canon) = root_canon else {
        return false;
    };
    let Ok(candidate_canon) = candidate.canonicalize() else {
        return false;
    };
    candidate_canon.starts_with(&root_canon)
}

let Ok(root_canon) = root_canon else {
        return false;
    };

let Ok(candidate_canon) = candidate.canonicalize() else {
        return false;
    };

fn resolve_special_context_files(root: &str, query: &str) -> Vec<PathBuf> {
    let mut results = Vec::new();
    let mut seen: HashSet<String> = HashSet::new();
    let query_lower = query.to_lowercase();

    if ENV_QUERY_KEYWORDS.iter().any(|k| query_lower.contains(k)) {
        for name in [".env.example", ".gitignore"] {
            let path = Path::new(root).join(name);
            if path.exists() && path.is_file() {
                let key = path.to_string_lossy().to_string();
                if seen.insert(key) {
                    results.push(path);
                }
            }
        }
    }

    results
}

fn append_special_notes(context: &mut String, root: &str, query: &str) {
