fn test_patcher_success() {
        use std::env;

        // Create temp file in current directory (test runs in project root)
        let temp_dir = env::current_dir().unwrap().join("target").join("test_temp");
        fs::create_dir_all(&temp_dir).ok();

        let file_path = temp_dir.join("test_file.txt");
        let mut file = fs::File::create(&file_path).unwrap();
        writeln!(file, "Original Content").unwrap();

        let new_content = "Patched Content";
        let path_str = file_path.to_str().unwrap();

        let root = env::current_dir().unwrap();
        let res = patcher::apply_patch(path_str, new_content, root.to_str().unwrap());
        assert!(res.is_ok(), "Patch failed: {:?}", res);

        let final_content = fs::read_to_string(&file_path).unwrap();
        assert_eq!(final_content, new_content);

        // Cleanup
        let _ = fs::remove_file(&file_path);
    }

fn test_patcher_file_not_found() {
        let root = std::env::current_dir().unwrap();
        let res = patcher::apply_patch(
            "/tmp/this_file_does_not_exist_12345.txt",
            "content",
            root.to_str().unwrap(),
        );
        assert!(res.is_err());
        let err_msg = res.unwrap_err().to_string();
        assert!(err_msg.contains("Security Violation"));
    }

fn test_patcher_rejects_symlink() {
        use std::env;
        use std::os::unix::fs::symlink;

        let root = env::current_dir().unwrap();
        let temp_dir = root.join("target").join("test_temp");
        fs::create_dir_all(&temp_dir).ok();

        let outside_path = env::temp_dir().join("guardian_symlink_target.txt");
        fs::write(&outside_path, "outside").unwrap();

        let link_path = temp_dir.join("symlink.txt");
        if link_path.exists() {
            let _ = fs::remove_file(&link_path);
        }
        symlink(&outside_path, &link_path).unwrap();

        let res = patcher::apply_patch(
            link_path.to_str().unwrap(),
            "content",
            root.to_str().unwrap(),
        );
        assert!(res.is_err(), "Symlink path should be rejected");

        let _ = fs::remove_file(&link_path);
        let _ = fs::remove_file(&outside_path);
    }

fn normalize_provider_id(provider_id: &str) -> String {
    let trimmed = provider_id.trim().to_lowercase();
    if trimmed.is_empty() {
        "ollama".to_string()
    } else {
        trimmed
    }
}

fn default_base_url(provider_id: &str) -> &'static str {
    match normalize_provider_id(provider_id).as_str() {
        "openai" => OPENAI_BASE_URL,
        "anthropic" => ANTHROPIC_BASE_URL,
        "gemini" => GEMINI_BASE_URL,
        "github-models" => GITHUB_MODELS_BASE_URL,
        "ollama-cloud" => OLLAMA_CLOUD_BASE_URL,
        _ => config::DEFAULT_HOST,
    }
}

fn filter_models(provider_id: &str, models: Vec<String>) -> Vec<String> {
    let id = normalize_provider_id(provider_id);
    if id == "ollama" {
        return models;
    }

    let mut filtered = Vec::new();
    for model in models.iter() {
        let normalized = normalize_model_id(model);
        let allowed = match id.as_str() {
            "openai" => {
                let blocked = [
                    "embedding",
                    "tts",
                    "whisper",
                    "audio",
                    "image",
                    "dall-e",
                    "moderation",
                    "realtime",
                    "speech",
                ];
                let is_chat = normalized.contains("gpt")
                    || normalized.starts_with("o1")
                    || normalized.starts_with("o3")
                    || normalized.contains("omni");
                let is_blocked = blocked.iter().any(|b| normalized.contains(b));
                is_chat && !is_blocked
            }
            "anthropic" => normalized.contains("claude"),
            "gemini" => normalized.contains("gemini") && !normalized.contains("embedding"),
            _ => true,
        };
        if allowed {
            filtered.push(model.clone());
        }
    }

    if filtered.is_empty() {
        models
    } else {
        filtered
    }
}

