    if is_local {
        DEFAULT_AI_REQUEST_CONCURRENCY_LOCAL
    } else {
        DEFAULT_AI_REQUEST_CONCURRENCY_CLOUD
    }
}

fn queue_key(provider_id: &str, _base_url: &str) -> String {
    let locality = if provider_id == "mock" || provider_id == "ollama" {
        "local"
    } else {
        "cloud"
    };
    format!("{provider_id}::{locality}")
}

let locality = if provider_id == "mock" || provider_id == "ollama" {
