fn ensure_valid_api_key(&self) -> Result<()> {
        if self.provider_id == "mock" || self.provider_id == "ollama" {
            return Ok(());
        }
        if config::is_placeholder_key(self.api_key.expose_secret()) && config::is_production() {
            anyhow::bail!("GUARDIAN_API_KEY is missing or still a placeholder");
        }
        Ok(())
    }

async fn acquire_request_slot(&self, class: AiRequestClass) -> Result<RequestSlot> {
        if self.queue.global.available_permits() == 0 {
            debug!(
                target: "guardian::ai",
                "AI request queued (provider={}, model={}, class={:?})",
                self.provider_id,
                self.model,
                class
            );
        }
        self.queue.acquire(class).await
    }

// Extract the first balanced JSON object/array from noisy model output.
// This is safer than naive first/last brace slicing and handles markdown wrappers.
fn sanitize_json_response(content: &str) -> &str {
        extract_first_balanced_json_slice(content).unwrap_or_else(|| content.trim())
    }

fn repair_invalid_json_escapes(content: &str) -> Option<String> {
        let mut output = String::with_capacity(content.len());
        let mut chars = content.chars().peekable();
        let mut in_string = false;
        let mut escaped = false;
        let mut changed = false;

        while let Some(ch) = chars.next() {
            if !in_string {
                if ch == '"' {
                    in_string = true;
                }
                output.push(ch);
                continue;
            }

            if escaped {
                output.push(ch);
                escaped = false;
                continue;
            }

            if ch == '\\' {
                let next = chars.peek().copied();
                let valid_escape = match next {
                    Some('"' | '\\' | '/' | 'b' | 'f' | 'n' | 'r' | 't') => true,
                    Some('u') => {
                        let mut lookahead = chars.clone();
                        lookahead.next();
                        let mut ok = true;
                        for _ in 0..4 {
                            match lookahead.next() {
                                Some(hex) if hex.is_ascii_hexdigit() => {}
                                _ => {
                                    ok = false;
                                    break;
                                }
                            }
                        }
                        ok
                    }
                    Some(_) | None => false,
                };

                if valid_escape {
                    output.push(ch);
                    escaped = true;
                } else {
                    output.push('\\');
                    output.push('\\');
                    changed = true;
                }
                continue;
            }

            if ch == '\r' || ch == '\n' || ch == '\t' {
                output.push('\\');
                output.push(match ch {
                    '\r' => 'r',
                    '\n' => 'n',
                    _ => 't',
                });
                changed = true;
                continue;
            }

            if ch == '"' {
                in_string = false;
            }
            output.push(ch);
        }

        if changed {
            Some(output)
        } else {
            None
        }
    }

let valid_escape = match next {
                    Some('"' | '\\' | '/' | 'b' | 'f' | 'n' | 'r' | 't') => true,
                    Some('u') => {
                        let mut lookahead = chars.clone();
                        lookahead.next();
                        let mut ok = true;
                        for _ in 0..4 {
                            match lookahead.next() {
                                Some(hex) if hex.is_ascii_hexdigit() => {}
                                _ => {
                                    ok = false;
                                    break;
                                }
                            }
                        }
                        ok
                    }
                    Some(_) | None => false,
                };

async fn send_chat(
        &self,
        system_prompt: &str,
        user_prompt: &str,
        json_mode: bool,
        class: AiRequestClass,
    ) -> Result<AiCall<String>> {
        let request_slot = self.acquire_request_slot(class).await?;
        let queue_wait_ms = request_slot.queue_wait_ms;
        let safe_user_prompt = crate::redaction::gate::mask_inline_secrets(user_prompt);
        let provider = self.provider_id.as_str();
        match provider {
            "mock" => {
                if json_mode {
                    let is_batch = system_prompt.contains("JSON ARRAY MODE")
                        || safe_user_prompt.starts_with("Batch Analysis Request");
                    if is_batch {
                        return Ok(AiCall {
                            value: "[]".to_string(),
                            queue_wait_ms,
                        });
                    }
                    return Ok(AiCall {
                        value: r#"{"file_path":"src/mock.ts","severity":"Info","message":"LGTM","suggestion":null,"chat_message":null,"suggested_diff":null}"#
                            .to_string(),
                        queue_wait_ms,
                    });
                }

                Ok(AiCall {
                    value: "MOCK: OK".to_string(),
                    queue_wait_ms,
                })
            }
            "ollama" => {
                let mut payload = json!({
                    "model": self.model,
                    "messages": [
                        { "role": "system", "content": system_prompt },
                        { "role": "user", "content": safe_user_prompt }
                    ],
                    "stream": false
                });
                if json_mode {
                    payload["format"] = json!("json");
                }
                let token = self.api_key.expose_secret().trim();
                let url = format!("{}/api/chat", self.base_url.trim_end_matches('/'));
                let mut request = self.client.post(&url);
                if !config::is_placeholder_key(token) {
                    request = request.bearer_auth(token);
                }

                let response = request.json(&payload).send().await.with_context(|| {
                    format!("Failed to send request to AI provider (url={})", url)
                })?;

                if !response.status().is_success() {
                    let error_text = response.text().await.unwrap_or_default();
                    anyhow::bail!("AI Request Failed: {}", error_text);
                }

                let response_json: serde_json::Value = response.json().await?;
                let content_str = response_json["message"]["content"]
                    .as_str()
                    .context("Invalid response format from AI")?;

                Ok(AiCall {
                    value: content_str.to_string(),
                    queue_wait_ms,
                })
            }
            "openai" => {
                let mut payload = json!({
                    "model": self.model,
                    "messages": [
                        { "role": "system", "content": system_prompt },
                        { "role": "user", "content": safe_user_prompt }
                    ],
                    "temperature": 0.2
                });
                if json_mode {
                    payload["response_format"] = json!({ "type": "json_object" });
                }
                let url = format!("{}/chat/completions", self.base_url.trim_end_matches('/'));
                let response = self
                    .client
                    .post(&url)
                    .bearer_auth(self.api_key.expose_secret())
                    .json(&payload)
                    .send()
                    .await
                    .context("Failed to send OpenAI request")?;
                if !response.status().is_success() {
                    let error_text = response.text().await.unwrap_or_default();
                    anyhow::bail!("OpenAI request failed: {}", error_text);
                }
                let response_json: serde_json::Value = response.json().await?;
                let content_str = response_json["choices"][0]["message"]["content"]
                    .as_str()
                    .context("Invalid OpenAI response format")?;
                Ok(AiCall {
                    value: content_str.to_string(),
                    queue_wait_ms,
                })
            }
            "anthropic" => {
                let payload = json!({
                    "model": self.model,
                    "max_tokens": 2048,
                    "system": system_prompt,
                    "messages": [
                        { "role": "user", "content": safe_user_prompt }
                    ]
                });
                let url = format!("{}/messages", self.base_url.trim_end_matches('/'));
                let response = self
                    .client
                    .post(&url)
                    .header("x-api-key", self.api_key.expose_secret())
                    .header("anthropic-version", "2023-06-01")
                    .json(&payload)
                    .send()
                    .await
                    .context("Failed to send Anthropic request")?;
                if !response.status().is_success() {
                    let error_text = response.text().await.unwrap_or_default();
                    anyhow::bail!("Anthropic request failed: {}", error_text);
                }
                let response_json: serde_json::Value = response.json().await?;
                let content = response_json["content"]
                    .as_array()
                    .context("Invalid Anthropic response format")?;
                let mut collected = String::new();
                for block in content {
                    if let Some(text) = block["text"].as_str() {
                        collected.push_str(text);
                    }
                }
                Ok(AiCall {
                    value: collected,
                    queue_wait_ms,
                })
            }
            "gemini" => {
                let model_path = if self.model.starts_with("models/") {
                    self.model.clone()
                } else {
                    format!("models/{}", self.model)
                };
                let payload = json!({
                    "systemInstruction": {
                        "parts": [{ "text": system_prompt }]
                    },
                    "contents": [
                        { "role": "user", "parts": [{ "text": safe_user_prompt }] }
                    ]
                });
                let url = format!(
                    "{}/{}:generateContent",
                    self.base_url.trim_end_matches('/'),
                    model_path
                );
                let response = self
                    .client
                    .post(&url)
                    .header("x-goog-api-key", self.api_key.expose_secret())
                    .json(&payload)
                    .send()
                    .await
                    .context("Failed to send Gemini request")?;
                if !response.status().is_success() {
                    let error_text = response.text().await.unwrap_or_default();
                    anyhow::bail!("Gemini request failed: {}", error_text);
                }
                let response_json: serde_json::Value = response.json().await?;
                let candidates = response_json["candidates"]
                    .as_array()
                    .context("Invalid Gemini response format")?;
                let mut collected = String::new();
                if let Some(first) = candidates.first() {
                    if let Some(parts) = first["content"]["parts"].as_array() {
                        for part in parts {
                            if let Some(text) = part["text"].as_str() {
                                collected.push_str(text);
                            }
                        }
                    }
                }
                Ok(AiCall {
                    value: collected,
                    queue_wait_ms,
