pub async fn analyze_diff(&self, file_path: &str, diff: &str) -> Result<AiCall<Critique>> {
        self.ensure_valid_api_key()?;
        let system_prompt = r#"You are 'Guardian', a high-authority Senior Software Architect & Security Auditor.
