fn skip_reason_label(path: &Path, is_chat: bool, profile: ScanProfile) -> Option<&'static str> {
    let decision = classify_path(path, is_chat, profile);
    if decision.include {
        return None;
    }
    Some(
        decision
            .reason
            .unwrap_or(SkipReason::IgnoredPathSegment)
            .as_str(),
    )
}

