fn strip_urls(query: &str) -> String {
    query
        .split_whitespace()
        .filter(|token| {
            let trimmed = token.trim();
            if trimmed.starts_with("site:") {
                return false;
            }
            let cleaned = trimmed
                .trim_start_matches(|c: char| matches!(c, '(' | '[' | '{' | '"' | '\''))
