struct UndoIndexEntry {
    applied_at: String,
    backup_file: String,
    bytes: u64,
}

fn canonicalize_path(path: &Path) -> Result<PathBuf> {
    #[cfg(windows)]
    {
        dunce::canonicalize(path).with_context(|| {
