normalizeUndoKey = (value: string, root?: string): string => {
    let out = (value || "").trim().replace(/\\/g, "/");
    if (!out) return "";

    if (root) {
      const rootNorm = root.trim().replace(/\\/g, "/").replace(/\/+$/, "");
      if (rootNorm && (out === rootNorm || out.startsWith(`${rootNorm}/`))) {
        out = out.slice(rootNorm.length);
      }
    }

    out = out.replace(/^\.\/+/, "");
    out = out.replace(/^\/+/, "");
    return out;
  }

