        }
      }
      await refreshEmbeddingSettings(false);
    };
    void syncEmbeddingConfig();
  }, [isDesktop]);

  useEffect(() => {
    if (!isDesktop || !settingsOpen) return;
    const loadEmbeddingOpenAiKeyStatus = async (): Promise<void> => {
