normalizeWebSearchDepth = useCallback((value: string | null): WebSearchDepth => {
    const raw = (value ?? "").trim().toLowerCase();
    if (raw === "advanced" || raw === "fast" || raw === "ultra-fast" || raw === "auto") {
      return raw as WebSearchDepth;
    }
    return "basic";
  }, [])

(value: string | null): WebSearchDepth => {
    const raw = (value ?? "").trim().toLowerCase();
    if (raw === "advanced" || raw === "fast" || raw === "ultra-fast" || raw === "auto") {
      return raw as WebSearchDepth;
    }
    return "basic";
  }

normalizeThemeMode = useCallback((value: unknown): ThemeMode => {
    const raw = String(value ?? "").trim().toLowerCase();
    if (raw === "light" || raw === "system") return raw;
    return "dark";
  }, [])

(value: unknown): ThemeMode => {
    const raw = String(value ?? "").trim().toLowerCase();
    if (raw === "light" || raw === "system") return raw;
    return "dark";
  }

normalizeLocale = useCallback((value: unknown): "en" | "tr" => {
    const raw = String(value ?? "").trim().toLowerCase();
    return raw === "tr" ? "tr" : "en";
  }, [])

(value: unknown): "en" | "tr" => {
    const raw = String(value ?? "").trim().toLowerCase();
    return raw === "tr" ? "tr" : "en";
  }

normalizeHex = useCallback((value: unknown, fallback: string): string => {
    const raw = String(value ?? "").trim();
    const valid = /^#[0-9a-fA-F]{6}$/.test(raw);
    return valid ? raw : fallback;
  }, [])

(value: unknown, fallback: string): string => {
    const raw = String(value ?? "").trim();
    const valid = /^#[0-9a-fA-F]{6}$/.test(raw);
    return valid ? raw : fallback;
  }

normalizeFontFamily = useCallback((value: unknown): string => {
    const raw = String(value ?? "")
      .trim()
      .toLowerCase();
    const allowList = new Set([
      "space-grotesk",
      "inter",
      "system-ui",
      "source-sans-3",
      "ibm-plex-sans",
    ]);
    return allowList.has(raw) ? raw : "space-grotesk";
  }, [])

(value: unknown): string => {
    const raw = String(value ?? "")
      .trim()
      .toLowerCase();
    const allowList = new Set([
      "space-grotesk",
      "inter",
      "system-ui",
      "source-sans-3",
      "ibm-plex-sans",
    ]);
    return allowList.has(raw) ? raw : "space-grotesk";
